CREATE OR REPLACE FUNCTION private.is_staff(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,private AS $$ SELECT private.has_role(_user_id,'admin'::public.app_role) OR private.has_role(_user_id,'teacher'::public.app_role) $$;
CREATE OR REPLACE FUNCTION private.teacher_can_access_class(_user_id uuid,_class_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,private AS $$ SELECT private.has_role(_user_id,'admin'::public.app_role) OR EXISTS(SELECT 1 FROM public.teacher_classes tc JOIN public.teachers t ON t.id=tc.teacher_id WHERE t.user_id=_user_id AND tc.class_id=_class_id) $$;